calleeMethods:
static inline __wsum csum_sub(__wsum csum, __wsum addend) /* <=== csum_sub */ 
{
	return csum_add(csum, ~addend);
}

static inline u32 /* <=== dst_metric */ 
dst_metric(const struct dst_entry *dst, const int metric)
{
	WARN_ON_ONCE(metric == RTAX_HOPLIMIT ||
		     metric == RTAX_ADVMSS ||
		     metric == RTAX_MTU);
	return dst_metric_raw(dst, metric);
}

static void ip6_append_data_mtu(unsigned int *mtu, /* <=== ip6_append_data_mtu */ 
				int *maxfraglen,
				unsigned int fragheaderlen,
				struct sk_buff *skb,
				struct rt6_info *rt,
				unsigned int orig_mtu)
{
	if (!(rt->dst.flags & DST_XFRM_TUNNEL)) {
		if (!skb) {
			/* first fragment, reserve header_len */
			*mtu = orig_mtu - rt->dst.header_len;

		} else {
			/*
			 * this fragment is not first, the headers
			 * space is regarded as data space.
			 */
			*mtu = orig_mtu;
		}
		*maxfraglen = ((*mtu - fragheaderlen) & ~7)
			      + fragheaderlen - sizeof(struct frag_hdr);
	}
}

static inline u32 /* <=== dst_allfrag */ 
dst_allfrag(const struct dst_entry *dst)
{
	int ret = dst_feature(dst,  RTAX_FEATURE_ALLFRAG);
	return ret;
}

static inline struct net *read_pnet(const possible_net_t *pnet) /* <=== read_pnet */ 
{
#ifdef CONFIG_NET_NS
	return pnet->net;
#else
	return &init_net;
#endif
}

static inline u32 /* <=== dst_feature */ 
dst_feature(const struct dst_entry *dst, u32 feature)
{
	return dst_metric(dst, RTAX_FEATURES) & feature;
}

static inline void skb_frag_size_add(skb_frag_t *frag, int delta) /* <=== skb_frag_size_add */ 
{
	frag->size += delta;
}

static inline bool ip6_sk_ignore_df(const struct sock *sk) /* <=== ip6_sk_ignore_df */ 
{
	return inet6_sk(sk)->pmtudisc < IPV6_PMTUDISC_DO ||
	       inet6_sk(sk)->pmtudisc == IPV6_PMTUDISC_OMIT;
}

static inline __wsum csum_add(__wsum csum, __wsum addend) /* <=== csum_add */ 
{
	u32 res = (__force u32)csum;
	res += (__force u32)addend;
	return (__force __wsum)(res + (res < (__force u32)addend));
}

static inline /* <=== sock_net */ 
struct net *sock_net(const struct sock *sk)
{
	return read_pnet(&sk->sk_net);
}

